        int[] st = new int[n], en = new int[n];
        for (int i = 0; i < n; i++) {
            st[i] = intervals.get(i).get(0);
            en[i] = intervals.get(i).get(1);
        }
        Arrays.sort(st);
        Arrays.sort(en);
        int rooms = 0, best = 0, j = 0;
        for (int s : st) {
            while (j < n && en[j] <= s) { j++; rooms--; }
            rooms++;
            best = Math.max(best, rooms);
        }
        return best;
    }

    static int bad = 0;
    static void check(Object got, Object exp) {
        String g = String.valueOf(got), e = String.valueOf(exp);
