    }
    static void done() { if (bad == 0) System.out.println("PASS"); }

    public static void main(String[] args) {
        check(minMeetingRooms(List.of(List.of(5, 7), List.of(1, 10), List.of(2, 3))), 2);
        check(minMeetingRooms(List.of(List.of(1, 2), List.of(2, 3))), 1);
        check(minMeetingRooms(List.of(List.of(1, 5), List.of(1, 5), List.of(5, 6), List.of(5, 6))), 2);
        check(minMeetingRooms(List.of(List.of(10, 20), List.of(1, 5), List.of(2, 6))), 2);
        check(minMeetingRooms(List.of()), 0);
        done();
    }
}
